600	    /**
601	     * Assigns the new owner's {@code householdId} when the request opts in with
602	     * {@code sharesHousehold} set to {@code true} and at least one existing owner already shares the
603	     * same last name and address (compared case-insensitively with runs of whitespace collapsed, the
604	     * same way {@link #rejectDuplicateHousehold} matches). The household's members and the new owner
605	     * all end up carrying one stable shared identifier: if any existing member already has a
606	     * {@code householdId} it is reused, otherwise a new one is derived from the normalized last name
607	     * and address. Any existing member that is missing the identifier is updated so the whole
608	     * household stays consistent. When the flag is absent, or set but no matching owner exists, no
609	     * identifier is assigned.
610	     */
611	    private void assignHousehold(Owner owner, OwnerFieldsDto ownerFieldsDto) {
612	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
613	            return;
614	        }
615	        String lastName = normalizeForComparison(owner.getLastName());
616	        String address = canonicalAddress(owner.getAddress());
617	        List<Owner> members = new ArrayList<>();
618	        for (Owner existing : this.clinicService.findAllOwners()) {
619	            if (lastName.equals(normalizeForComparison(existing.getLastName()))
620	                && address.equals(canonicalAddress(existing.getAddress()))) {
621	                members.add(existing);
622	            }
623	        }
624	        if (members.isEmpty()) {
625	            return;
626	        }
627	        String householdId = members.stream()
628	            .map(Owner::getHouseholdId)
629	            .filter(id -> id != null && !id.isBlank())
630	            .findFirst()
631	            .orElseGet(() -> newHouseholdId(lastName, address));
632	        owner.setHouseholdId(householdId);
633	        for (Owner member : members) {
634	            if (!householdId.equals(member.getHouseholdId())) {
635	                member.setHouseholdId(householdId);
636	                this.clinicService.saveOwner(member);
637	            }
638	        }
639	    }
