641	    /**
642	     * Derives a stable household identifier from the normalized last name and address: the first
643	     * twelve upper-case hex characters of the SHA-256 digest of {@code "<lastName>|<address>"}. Two
644	     * owners in the same household therefore derive the same value regardless of creation order.
645	     */
646	    private static String newHouseholdId(String normalizedLastName, String normalizedAddress) {
647	        try {
648	            byte[] digest = MessageDigest.getInstance("SHA-256")
649	                .digest((normalizedLastName + "|" + normalizedAddress).getBytes(StandardCharsets.UTF_8));
650	            StringBuilder hex = new StringBuilder(digest.length * 2);
651	            for (byte b : digest) {
652	                hex.append(String.format("%02x", b));
653	            }
654	            return hex.substring(0, 12).toUpperCase(Locale.ROOT);
655	        } catch (NoSuchAlgorithmException ex) {
656	            throw new IllegalStateException("SHA-256 is required but unavailable", ex);
657	        }
658	    }
659	}

